        self.primitive(b"openout", EXTENSION, OPEN_NODE)?;
        self.primitive(b"write", EXTENSION, WRITE_NODE)?;
        self.write_loc = self.cur_val;
        self.primitive(b"closeout", EXTENSION, CLOSE_NODE)?;
